module IIC_Driver(
	sys_clk,
	rst_n,
	IICSlave,
	IICWriteReq,
	IICWriteData,
	IICSCL,
	IICWriteDone,
	IICSDA);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [15:0] IICSlave;
	input IICWriteReq;
	input [7:0] IICWriteData;
	output IICSCL;
	output IICWriteDone;
	inout IICSDA;

	wire sys_clk;
	wire rst_n;
	wire [15:0] IICSlave;
	wire IICWriteReq;
	wire [7:0] IICWriteData;
	wire IICSCL;
	wire IICWriteDone;
	wire IICSDA;

	//----Code starts here: integrated by Robei-----
	wire      IICReadReq =1'b0;     
	wire      IICReadDone;    
	wire[7:0]IICReadData;      
	
	localparam IIC_IDLE         =   6'b000_001;        //空闲态
	localparam IIC_START     =   6'b000_010;        //起始态
	localparam IIC_WRDATA   =   6'b000_100;       //写数据态
	localparam IIC_RDDATA    =   6'b001_000;      //读数据态
	localparam IIC_ACK           =   6'b010_000;      //应答态
	localparam IIC_STOP        =   6'b100_000;      //停止态
	localparam  IIC_Pre            =   3'd4;   
	
	reg   iictx;    
	reg   iicCLK;       
	reg[5:0]   state , next_state;
	reg[21:0]  IICCnt;              
	reg[3:0]   IICBitCnt;          
	reg[1:0]   IICACKStopCnt;       
	reg[2:0]   IICSendBytes;       
	reg[15:0]   IICSlaveReg;         
	reg[7:0]   IICReadDataReg;      
	reg 	IICWriteReqReg;
	
	assign IICSDA = (state == IIC_RDDATA || (state == IIC_ACK)) ? 1'bz : iictx;  
	assign IICSCL =  iicCLK;
	assign IICReadData = IICReadDataReg;
	assign IICReadDone  = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	assign IICWriteDone = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteDone == 1'b1)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteReq == 1'b1)
		   IICWriteReqReg <= 1'b1;
		else
			IICWriteReqReg <= IICWriteReqReg;
	end
	
	always @(posedge sys_clk or negedge rst_n) 
	begin
	    if(rst_n == 1'b0)
	        state <= IIC_IDLE;
	    else
	        state <= next_state;   
	end
	
	always @(*)
	begin
	    case(state)
	    IIC_IDLE: 
	        if(IICWriteReq == 1'b1 || IICReadReq == 1'b1)
	            next_state <= IIC_START;
	        else
	            next_state <= IIC_IDLE;
	    IIC_START:
	        if(IICCnt == (IIC_Pre * 'd2))
	            next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_START;
	    IIC_WRDATA:
	        if(IICBitCnt == 'd8&& iicCLK == 1'b0)
	            next_state <= IIC_ACK;
	        else
	            next_state <= IIC_WRDATA;
	    IIC_RDDATA:
	        if(IICBitCnt == 'd8 && IICCnt == IIC_Pre /4 && iicCLK == 1'b0)
	            next_state <= IIC_ACK;
	        else
	            next_state <= IIC_RDDATA;
	    IIC_ACK:
	        if(IICACKStopCnt == 'd1 && iicCLK == 1'b0)
	            if(IICSendBytes == 'd2) 
	                if(IICWriteReqReg == 1'b1)           
	                    next_state <= IIC_STOP;
	                else 
	                    next_state <= IIC_RDDATA;
	            else if(IICSendBytes == 'd2 && IICReadReq == 1'b1)
	                next_state <= IIC_START;
	            else if(IICSendBytes == 'd4)
	                next_state <= IIC_STOP;
	            else
	                next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_ACK;
	    IIC_STOP:
	        if(IICACKStopCnt == 'd1 && IICCnt == IIC_Pre/4 && iicCLK == 1'b1)
	            next_state <= IIC_IDLE;
	        else
	            next_state <= IIC_STOP;
	    default:  next_state <= IIC_IDLE;
	    endcase
	end
	//IIC 发送字节计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_IDLE)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_ACK)
	        if(next_state != state)
	            IICSendBytes <= IICSendBytes + 1'b1;
	        else
	            IICSendBytes <= IICSendBytes;
	    else
	        IICSendBytes <= IICSendBytes;
	
	end
	//IIC分频计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICCnt <= 'd0;
	    else if(IICCnt == IIC_Pre && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(IICCnt == (IIC_Pre *'d2) && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(state != next_state)
	        IICCnt <= 'd0;
	    else if(state == IIC_START)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_WRDATA )
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_RDDATA)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_ACK)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_STOP)
	        IICCnt <= IICCnt + 1'b1;
	end
	
	//IIC发送bit计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_IDLE || state == IIC_ACK)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_WRDATA && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICBitCnt <= IICBitCnt + 1'b1;
	        else
	            IICBitCnt <= IICBitCnt;
	    else if(state == IIC_RDDATA && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICBitCnt <= IICBitCnt + 1'b1;
	        else
	            IICBitCnt <= IICBitCnt;
	    else
	        IICBitCnt <= IICBitCnt;
	end
	
	//IIC ack stop应答计数
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICACKStopCnt <= 'd0;
	    else if(state != next_state)
	        IICACKStopCnt <= 'd0;
	    else if((state == IIC_ACK || state == IIC_STOP) && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICACKStopCnt <= IICACKStopCnt + 1'b1;
	        else
	            IICACKStopCnt <= IICACKStopCnt;
	    else if(state == IIC_ACK || state == IIC_STOP)
	        IICACKStopCnt <= IICACKStopCnt;
	    else
	        IICACKStopCnt <= 'd0;
	end
	
	//IIC从机信息控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSlaveReg <= 'd0;
	    else if((IICWriteReq == 1'b1 || IICReadReq == 1'b1) && state == IIC_IDLE)  
	        IICSlaveReg <= IICSlave;
	    else if(state == IIC_ACK && state != next_state)   
	        if(IICSendBytes == 'd2)
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]} + 1'b1;
	        else
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]};
	    else
	        IICSlaveReg <= IICSlaveReg;
	end
	
	//IIC 时钟控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre*2))    
	        iicCLK <= 1'b0;
	    else if(state == IIC_START && IICCnt > IIC_Pre)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == IIC_Pre)
	        iicCLK <= iicCLK;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre)    
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_RDDATA && IICCnt == IIC_Pre)    
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_ACK && IICCnt == IIC_Pre)
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_STOP && IICCnt == IIC_Pre) 
	        iicCLK <= 1'b1;
	end
	
	//iic 发送控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)   
	        iictx <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre/2))  
	        iictx <= 1'b0;
	    else if(state == IIC_START && IICCnt == IIC_Pre/4)     
	        iictx <= 1'b1;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre / 2)
	        if(iicCLK == 1'b0 && IICSendBytes == 'd2 && (IICWriteReq == 1'b1 || IICWriteReqReg == 1'b1))
	            iictx <= IICWriteData['d7-IICBitCnt];
	        else if(iicCLK == 1'b0)
	            iictx <= IICSlaveReg['d7-IICBitCnt];
	        else
	            iictx <= iictx;
	    else if(state == IIC_ACK)
	        iictx <= 1'b0;
	
	    else if(state == IIC_STOP && IICCnt == (IIC_Pre))
	        if(iicCLK == 1'b1)
	            iictx <= 1'b1;
	        else
	            iictx <= iictx;
	    else if(state == IIC_IDLE)
	        iictx <= 1'b1;
	end
	
	//iic 读取数据控制
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICReadDataReg <= 'd0;
	    else if(state == IIC_RDDATA && IICCnt == IIC_Pre / 2)
	        if(iicCLK == 1'b1)
	            IICReadDataReg <= {IICReadDataReg[6:0],IICSDA};
	        else
	            IICReadDataReg <= IICReadDataReg;
	    else
	        IICReadDataReg <= IICReadDataReg;
	end
	
	
	
	
	
	
endmodule    //IIC_Driver

